# DEFAULT SSL CATCH-ALL
server {
    listen 443 ssl http2 default_server;
    listen [::]:443 ssl http2 default_server;
    server_name _;

    ssl_certificate /etc/letsencrypt/live/aenews.net/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/aenews.net/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;

    return 444;

    access_log /var/log/nginx/default-ssl-blocked.access.log;
    error_log /var/log/nginx/default-ssl-blocked.error.log warn;
}
upstream admin_aenews_net {
    server 127.0.0.1:3182;
}

upstream api_aenews_net {
    server 127.0.0.1:3181;
}

server {
    listen 80;
    server_name admin.aenews.net;
    location /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://$server_name$request_uri; }
}

server {
    listen 443 ssl http2;
    server_name admin.aenews.net;
    ssl_certificate /etc/nginx/ssl/admin.aenews.net/fullchain.pem;
    ssl_certificate_key /etc/nginx/ssl/admin.aenews.net/privkey.pem;

    location = / {
        return 301 https://admin.aenews.net/admin/;
    }

    location /api/ {
        proxy_pass http://api_aenews_net;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 120s;
    }

    location / {
        proxy_pass http://admin_aenews_net;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
    }
}
